#include "country_summary.h"
#include "store.h"
#include <iostream>
#include <fstream>
#include <unistd.h>
#define CHECK(x) do{if(!(x)){std::cerr<<"Failed "<<__LINE__<<": "<<#x<<'\n';return 1;}}while(0)
int main(){
 std::vector<dx::Row> rows;for(int i=0;i<8;i++){dx::Decode d;d.utc=1800000000+i;d.identity.transmitter="K"+std::to_string(i)+"ABC";d.country=i<7?"Country A":"Country B";d.snr=-10;d.km=i<7?std::optional<double>{1000}:std::nullopt;rows.push_back({d});}auto changed=rows.front();changed.decode.utc+=20;changed.decode.snr=-24;changed.decode.km=2400;rows.push_back(changed);auto noIdentity=changed;noIdentity.decode.identity.transmitter.clear();noIdentity.decode.snr=100;rows.push_back(noIdentity);
 auto summaries=dx::countrySummaries(rows);CHECK(summaries.size()==2&&summaries[0].country=="Country A");auto a=summaries[0];CHECK(a.stations==7&&a.distanceSamples==7&&a.averageKm&&*a.averageKm==1200&&a.averageSnr==-12&&a.latestSenders.size()==5&&dx::senderList(a)=="K0ABC, K6ABC, K5ABC, K4ABC, K3ABC");CHECK(!summaries[1].averageKm&&summaries[1].stations==1);for(bool descending:{false,true})CHECK(dx::countrySummaries(rows,2,descending).back().country=="Country B");CHECK(dx::countrySummaries(rows,1,true).front().stations==7);
 CHECK(dx::cornerFlashOpacity(0)==0&&dx::cornerFlashOpacity(1)>.999&&dx::cornerFlashOpacity(2)==0&&dx::cornerFlashOpacity(3)==0&&dx::cornerFlashOpacity(.5)==dx::cornerFlashOpacity(1.5));
 auto path=std::filesystem::temp_directory_path()/("dx-country-table-"+std::to_string(getpid())+".sqlite3");{dx::Store store(path);for(int i=0;i<9;i++){dx::Decode d;d.utc=1800000000+i;d.dial=7074000;d.mode="FT8";d.snr=-12;d.audio=1000;d.message="CQ K"+std::to_string(i)+"ABC FN42";d.country="Country "+std::to_string(i);CHECK(store.insert(d,{39.5,33}));}auto update=store.stats(1800000100).latestCountries.back();update.utc=1800000100;update.message="G1ABC K0ABC -07";update.snr=-7;CHECK(store.insert(update,{39.5,33}));auto sameSlot=update;sameSlot.snr=-5;sameSlot.message="G2ABC K0ABC -05";CHECK(store.insert(sameSlot,{39.5,33}));auto stats=store.sessionStats(sameSlot.utc,0,0);CHECK(stats.latestCountries.size()==9&&stats.latestCountries.front().country=="Country 0"&&stats.latestCountries.front().message==sameSlot.message&&stats.latestCountries.front().snr==-5);CHECK(stats.farthestReception&&stats.farthestReception->km==stats.farthest&&stats.farthestReception->country==stats.farthestCountry);auto cutoff=store.lastReceptionId();CHECK(store.sessionStats(sameSlot.utc,cutoff,sameSlot.utc).latestCountries.empty());CHECK(!store.sessionStats(sameSlot.utc,cutoff,sameSlot.utc).farthestReception);
  dx::Query q;q.messages=true;q.sort=18;auto messages=store.rows(q);CHECK(messages.size()==11&&messages[0].decode.message==sameSlot.message&&messages[1].decode.message==update.message);q.sort=19;CHECK(store.rows(q).size()==11);q.filter.source="live";CHECK(store.rows(q).size()==11&&dx::Filter::fromJson(q.filter.json()).source=="live");q.filter.source="legacy";CHECK(store.rows(q).empty());q.filter={};q.messages=false;q.uniqueCalls=true;q.countries=true;q.sort=5;auto output=path.string()+".json";store.exportRows(q,output,false);std::ifstream in(output);dx::Json json;in>>json;CHECK(json.size()==9&&json[0]["stations"]==1&&json[0]["last_5_senders"]==dx::Json::array({"K0ABC"}));std::filesystem::remove(output);
 }std::filesystem::remove(path);std::filesystem::remove(path.string()+"-wal");std::filesystem::remove(path.string()+"-shm");std::cout<<"Distinct-country latest rows, unbiased station averages, repeated messages, exports and pulse timing passed\n";
}
